insert into source_references (source_type, url, title, organization, status, received_on, verified_on, document_reference)
select 'ministry_of_education',
  'http://www.moe.gov.cn/jyb_xxgk/s5743/s5744/202606/t20260618_1441074.html',
  '全国高等学校名单',
  '中华人民共和国教育部',
  'officially_verified',
  date '2026-06-18',
  date '2026-11-08',
  '截至2026年6月17日'
where not exists (select 1 from source_references where url = 'http://www.moe.gov.cn/jyb_xxgk/s5743/s5744/202606/t20260618_1441074.html');

