select 'moe-4111010001', country.id, province.id, (select city.id from cities city join provinces province on province.id = city.province_id where province.name_zh = '北京市' and city.name_zh = '北京市'), '4111010001', '北京大学', 'regular_undergraduate', null, '教育部', 'undergraduate', null, '北京市', null, true, 'unknown', 'unpublished', 'published', 'officially_verified', timestamptz '2026-11-08 00:00:00+00', false, source.id
from countries country
join provinces province on province.country_id = country.id and province.name_zh = '北京市'
join source_references source on source.url = 'http://www.moe.gov.cn/jyb_xxgk/s5743/s5744/202606/t20260618_1441074.html'
where country.code = 'CN'
and not exists (select 1 from universities where institution_code = '4111010001');
